mapper.insert:
insert into CHB_PRD_POSITION (CDATE, PROD_ID, INDENTIFY_MARK,CCY, ISSUE_PARTY_ID, TDADD_QTY, TDADD_AMT, TDADD_COST, TDADD_INTAMT,BALANCE_QTY, BALANCE_AMT, TOTAL_INTAMT,ORG_CODE,DEPT_CODE, CREATE_USER,CREATE_TIME, REMARK) values (
select #{dto.cdate,jdbcType=DATE}, #{dto.prodId,jdbcType=VARCHAR}, #{dto.indentifyMark,jdbcType=VARCHAR}, #{dto.ccy,jdbcType=VARCHAR}, #{dto.issuePartyId,jdbcType=VARCHAR}, #{dto.tdaddQty,jdbcType=DECIMAL}, #{dto.tdaddAmt,jdbcType=DECIMAL}, #{dto.tdaddCost,jdbcType=DECIMAL}, #{dto.tdaddIntamt,jdbcType=DECIMAL}, #{dto.balanceQty,jdbcType=DECIMAL}, #{dto.balanceAmt,jdbcType=DECIMAL}, #{dto.totalIntamt,jdbcType=DECIMAL}, #{dto.orgCode,jdbcType=VARCHAR}, #{dto.deptCode,jdbcType=VARCHAR}, #{dto.createUser,jdbcType=VARCHAR}, NOW(), #{dto.remark,jdbcType=VARCHAR} from dual
)

mapper.delete:
delete from
CHB_PRD_POSITION
where CDATE >= #{cdate,jdbcType=DATE}

	and PROD_ID in

		#{accountid}

mapper.select:
SELECT ifnull(DEAL.FPROD_ID,DEAL.PROD_ID) prodId, DEAL.ISSUE_PARTY_ID issuePartyId, DEAL.INDENTIFY_MARK indentifyMark, (case DEAL.TRADE_TYPE when'04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end)as settdateDate, DEAL.CCY ccy, /*SUM(ifnull((case DEAL.TRADE_TYPE when '14' then 0 when '15' then 0 else DEAL.TRADE_PRINCE end),0)) tradePrince,*/ SUM(ifnull(DEAL.TRADE_PRINCE,0)) tradePrince, SUM(ifnull(DEAL.TRADE_QTY,0)) tradeQty, SUM(ifnull(DEAL.INT_AMT,0)) intAmt, INFO.PRODTYPE prodType, DEAL.ORG_CODE orgCode, SUM(ifnull(DEAL.CUST_COUNTS,0)) custCounts, /*SUM(ifnull((case DEAL.TRADE_TYPE when '05' then 0 else DEAL.TRADE_COST end),0)) tradeCost,*/ SUM(ifnull(DEAL.TRADE_COST,0)) tradeCost, ifnull(DEAL.ISAGENCY,'02') isagency, DEAL.BUY_PLACE buyPlace, DEAL.CUSTOMER_TYPE1 customerType1, DEAL.CUSTOMER_TYPE2 customerType2, INFO.VDATE FROM CHB_PRD_DEAL DEAL
LEFT JOIN CHB_PRD_BASEINFO INFO ON ifnull(DEAL.FPROD_ID,DEAL.PROD_ID) = INFO.PROD_ID AND INFO.STATUS!='D'
WHERE DEAL.STATUS != 'D' and INFO.STATUS!='D' and (deal.BUY_PLACE not in('210200','330200','350200','370200','440300') or deal.BUY_PLACE is null) AND (case DEAL.TRADE_TYPE when'04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end) = #{bookDate,jdbcType = DATE}
AND ifnull(DEAL.FPROD_ID,DEAL.PROD_ID) in
#{accountid}
AND DEAL.INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}
AND DEAL.CCY = #{ccy,jdbcType=VARCHAR}
AND DEAL.ISSUE_PARTY_ID = #{issuePartyId,jdbcType=VARCHAR}
AND DEAL.TRADE_TYPE IN
#{dealtype}
AND DEAL.BUY_PLACE = #{buyPlace,jdbcType=VARCHAR}
GROUP BY ifnull(DEAL.FPROD_ID,DEAL.PROD_ID), DEAL.ISSUE_PARTY_ID, DEAL.INDENTIFY_MARK, (case DEAL.TRADE_TYPE when'04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end), DEAL.CCY, INFO.PRODTYPE, DEAL.ORG_CODE, ifnull(DEAL.ISAGENCY,'02'), DEAL.BUY_PLACE, DEAL.CUSTOMER_TYPE1, DEAL.CUSTOMER_TYPE2, info.vdate order by ifnull(DEAL.FPROD_ID,DEAL.PROD_ID),ifnull(DEAL.ISAGENCY,'02')

SELECT DATE_ADD(POS.CDATE,INTERVAL 1 DAY) CDATE, POS.PROD_ID, POS.INDENTIFY_MARK, POS.CCY, POS.ISSUE_PARTY_ID, POS.BALANCE_QTY, POS.BALANCE_AMT, POS.TOTAL_INTAMT, POS.ORG_CODE, POS.DEPT_CODE, B.VDATE, POS.BUY_PLACE, POS.CONSIGN_AMT, POS.CUST_COUNTS, POS.CUSTOMER_TYPE2, POS.CUSTAMT, POS.CUSTQTY, POS.RAISEAMT FROM CHB_PRD_POSITION POS LEFT JOIN CHB_PRD_BASEINFO B ON POS.PROD_ID=B.PROD_ID WHERE 1 = 1 AND POS.CDATE = #{cdate,jdbcType = DATE}
AND POS.PROD_ID in
#{accountid}
/*未到期且后续没有待支付的付息交易*/ AND NOT EXISTS ( SELECT 1 FROM CHB_PRD_DEAL DL WHERE ifnull(FPROD_ID,PROD_ID) = POS.PROD_ID AND DL.SETTDATE_DATE = POS.CDATE AND DL.TRADE_TYPE = '16' AND DL.STATUS != 'D' AND NOT EXISTS (SELECT 1 FROM CHB_PRD_DEAL T1 WHERE T1.PROD_ID = DL.PROD_ID AND T1.TRADE_TYPE = '04' AND T1.STATUS != 'D' AND T1.INTEREST_DATE > DL.SETTDATE_DATE) )

SELECT
case
when min(SETTDATE_DATE) is  null
then #{batchDate,jdbcType=DATE}
when min(SETTDATE_DATE) is not null and min(SETTDATE_DATE)>#{batchDate,jdbcType=DATE}
then #{batchDate,jdbcType=DATE}
when min(SETTDATE_DATE) is not null and min(SETTDATE_DATE)<=#{batchDate,jdbcType=DATE}
then  min(SETTDATE_DATE) end  SETTDATEDATE
FROM CHB_PRD_DEAL
WHERE
DATE_FORMAT(update_time,'%Y-%m-%d')=DATE_FORMAT(#{batchDate,jdbcType=DATE},'%Y-%m-%d')

	AND ifnull(FPROD_ID,PROD_ID) in

		#{accountid}

select  VDATE  FROM CHB_PRD_BASEINFO
WHERE  PROD_ID=#{prodId,jdbcType = VARCHAR}
AND  status !='D'
